772	// 已有数据损坏时明确报错，不能当成空台账继续。
773	func TestCorruptData(t *testing.T) {
774		dir := t.TempDir()
775		// 先写入有效数据。
776		s, err := Open(dir)
777		if err != nil {
778			t.Fatal(err)
779		}
