834		for i := 0; i < 20; i++ {
835			if _, err := s.AddFeeding(fmt.Sprintf("f-%s-%03d", id, i), "B1", "M1", "1",
836				time.Now(), "登记人"+id); err != nil {
837				fmt.Fprintf(os.Stderr, "helper feed: %v\n", err)
838				os.Exit(1)
